import "errors"

func SafeDivide(dividend, divisor float64) (float64, error) {
	if divisor == 0 {
		return 0, errors.New("division by zero")
	}
	return dividend / divisor, nil
}

func MinMax(numbers ...int) (min int, max int, err error) {
	if len(numbers) == 0 {
		return 0, 0, errors.New("empty numbers list")
	}
	min = numbers[0]
	max = numbers[0]
	for _, n := range numbers[1:] {
		if n < min {
			min = n
		}
		if n > max {
			max = n
		}
	}
	return min, max, nil
}

func Filter(numbers []int, predicate func(int) bool) []int {
	var result []int
	for _, n := range numbers {
		if predicate(n) {
			result = append(result, n)
		}
	}
	return result
}
